// ─── carIcon.ts ──────────────────────────────────────────────────────────────
// Returns an SVG string for the animated car marker.
// The SVG is centred at (24, 24) so Google Maps rotation works correctly.

import type { TripPassenger } from "./types/tracking.types";
// Status color/label lookup — mirrors paxTrackingStatusColors from TimelineItem.tsx
// for visual consistency between the timeline list and the map InfoWindow.
const INFO_STATUS_COLORS: Record<string, { bg: string; text: string, border: string }> = {
  Pending: { bg: "#FEF9C3", text: "#713F12", border: "none" },
  "No-Show": { bg: "#FEE2E2", text: "#991B1B", border: "none" },
  "Not-Boarded": { bg: "#FFEDD5", text: "#9A3412", border: "none" },
  Boarded: { bg: "#DBEAFE", text: "#1D4ED8", border: "none" },
  "Trip-Completed": { bg: "#D1FAE5", text: "#065F46", border: "none" },
  "De-Boarded": { bg: "#FEF3C7", text: "#92400E", border: "none" },
  "En-Route": { bg: "#EDE9FE", text: "#5B21B6", border: "none" },
  "Reached-Home": { bg: "#D1FAE5", text: "#065F46", border: "none" },
};

/** Escapes basic HTML-sensitive characters before interpolating into InfoWindow markup. */
function escapeHtml(value: string | number | null | undefined): string {
  if (value == null) return "";
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function buildCarSVG(color = "#1d4ed8"): string {
  return `
<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 48 48">
  <!-- Soft drop-shadow -->
  <ellipse cx="24" cy="43" rx="10" ry="3.5" fill="rgba(0,0,0,0.22)"/>

  <!-- Car body -->
  <rect x="10" y="18" width="28" height="18" rx="5" fill="${color}"/>

  <!-- Cabin / roof -->
  <path d="M15 18 Q17 8 24 8 Q31 8 33 18Z" fill="${color}" opacity="0.9"/>

  <!-- Windscreen -->
  <path d="M17 18 Q19 10 24 10 Q29 10 31 18Z" fill="#bfdbfe" opacity="0.7"/>

  <!-- Front lights -->
  <rect x="11" y="31" width="5" height="3" rx="1.5" fill="#fef08a"/>
  <rect x="32" y="31" width="5" height="3" rx="1.5" fill="#fef08a"/>

  <!-- Rear lights -->
  <rect x="11" y="19" width="4" height="3" rx="1.5" fill="#fca5a5"/>
  <rect x="33" y="19" width="4" height="3" rx="1.5" fill="#fca5a5"/>

  <!-- Wheels -->
  <circle cx="15" cy="36" r="4.5" fill="#1e293b"/>
  <circle cx="15" cy="36" r="2"   fill="#94a3b8"/>
  <circle cx="33" cy="36" r="4.5" fill="#1e293b"/>
  <circle cx="33" cy="36" r="2"   fill="#94a3b8"/>
</svg>`.trim();
}
